    const TITLE_COLLAPSED = '🔍 搜索';

    // 高亮相关配置
    const HL_DELAY   = 150;            // 输入防抖（毫秒），越小越跟手、越大越省性能
    const MAX_HITS   = 800;            // 单次最多高亮数量，防止超大页面卡死
